import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;


public class CodeForce308C {

    public static void main(String[] args) throws IOException {

        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer token = new StringTokenizer(in.readLine());
        Long w = Long.parseLong(token.nextToken());
        Long m = Long.parseLong(token.nextToken());
        if(w==2) {
            System.out.println("YES");
        }
        Long start = System.currentTimeMillis();

        List<Long> combination = new ArrayList<Long>();
        for(int i=0;i<=100;i++) {
            long num = (long)Math.pow(w, i);
            if(num>(long)2*Integer.MAX_VALUE) {
//              if(num>(long)2*m) {
                break;
            }

            combination.add(num);
            int till=combination.size()-1;
            for(int j=0;j<till;j++) {
                combination.add(combination.get(j)+num);
            }
        }
//      System.out.println(System.currentTimeMillis()-start);
        Collections.sort(combination);
        if(Collections.binarySearch(combination, m)>=0) {
            System.out.println("YES");
            return;
        }
        for (Long element : combination) {
//          if(Collections.binarySearch(combination, element+m)>=0 || Collections.binarySearch(combination, Math.abs(element-m))>=0) {
                if(Collections.binarySearch(combination, element+m)>=0) {
                System.out.println("YES");
                return;
            }
        }
        System.out.println("NO");

    }

}

